const express = require('express');
const path = require('path');
const db = require('./db');

const app = express();
const PORT = process.env.PORT || 3000;
const HOST = '0.0.0.0';

app.use(express.json({ limit: '50mb' }));
app.use(express.urlencoded({ extended: true, limit: '50mb' }));
app.use(express.static(path.join(__dirname, 'public')));

// Ensure database is initialized
db.getDb();

// List all reports
app.get('/api/reports', (req, res) => {
  try {
    const reports = db.listDocuments();
    res.json(reports);
  } catch (err) {
    console.error('Error listing reports:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Get a single report
app.get('/api/reports/:id', (req, res) => {
  try {
    const doc = db.getDocument(req.params.id);
    if (!doc) {
      return res.status(404).json({ error: 'Document not found' });
    }
    res.json(doc);
  } catch (err) {
    console.error('Error fetching report:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Save a report handler
function handleSave(req, res) {
  const { id } = req.params;
  const { baseRevision, content, documentId, comment } = req.body;

  // Validation
  if (documentId !== undefined && documentId !== null && documentId !== id) {
    return res.status(400).json({ error: 'documentId does not match the target document' });
  }

  if (baseRevision === undefined || typeof baseRevision !== 'number' || !Number.isInteger(baseRevision)) {
    return res.status(400).json({ error: 'baseRevision must be an integer' });
  }

  if (content === undefined || typeof content !== 'string') {
    return res.status(400).json({ error: 'content must be a string' });
  }

  try {
    const result = db.saveDocument(id, baseRevision, content, comment);
    return res.status(200).json(result);
  } catch (err) {
    if (err.status === 404) {
      return res.status(404).json({ error: err.message });
    }
    if (err.status === 409) {
      return res.status(409).json({
        error: err.message,
        serverRevision: err.currentRevision
      });
    }
    console.error('Save error:', err);
    return res.status(500).json({ error: 'Internal server error' });
  }
}

app.post('/api/reports/:id/save', handleSave);
app.put('/api/reports/:id', handleSave);
app.post('/api/reports/:id', handleSave);

// Get revision history for a report
app.get('/api/reports/:id/revisions', (req, res) => {
  try {
    const doc = db.getDocument(req.params.id);
    if (!doc) {
      return res.status(404).json({ error: 'Document not found' });
    }
    const revisions = db.getRevisions(req.params.id);
    res.json(revisions);
  } catch (err) {
    console.error('Error fetching revisions:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Get a specific revision's content
app.get('/api/reports/:id/revisions/:revNum', (req, res) => {
  try {
    const revNum = parseInt(req.params.revNum, 10);
    if (isNaN(revNum)) {
      return res.status(400).json({ error: 'Invalid revision number' });
    }
    const revision = db.getRevisionContent(req.params.id, revNum);
    if (!revision) {
      return res.status(404).json({ error: 'Revision not found' });
    }
    res.json(revision);
  } catch (err) {
    console.error('Error fetching revision content:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Serve frontend SPA fallback
app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'index.html'));
});

// Start listening
if (require.main === module) {
  app.listen(PORT, HOST, () => {
    console.log(`PatchPad server listening on http://${HOST}:${PORT}`);
  });
}

module.exports = app;

// Grapheme cluster and Unicode utilities for PatchPad

const segmenter = (typeof Intl !== 'undefined' && Intl.Segmenter)
  ? new Intl.Segmenter('en', { granularity: 'grapheme' })
  : null;

/**
 * Returns an array of grapheme segments for a string
 * @param {string} str 
 * @returns {Array<{ segment: string, index: number }>}
 */
function getGraphemeSegments(str) {
  if (!str) return [];
  if (segmenter) {
    return Array.from(segmenter.segment(str));
  }
  // Fallback for environments without Intl.Segmenter
  const segments = [];
  let index = 0;
  for (const ch of str) {
    segments.push({ segment: ch, index });
    index += ch.length;
  }
  return segments;
}

/**
 * Get the previous grapheme cluster boundary before the given character column
 * @param {string} str 
 * @param {number} col 
 * @returns {number}
 */
function prevGraphemeBoundary(str, col) {
  if (col <= 0) return 0;
  if (col > str.length) col = str.length;
  const segs = getGraphemeSegments(str);
  let prevIndex = 0;
  for (const s of segs) {
    if (s.index >= col) {
      return prevIndex;
    }
    prevIndex = s.index;
  }
  return prevIndex;
}

/**
 * Get the next grapheme cluster boundary after the given character column
 * @param {string} str 
 * @param {number} col 
 * @returns {number}
 */
function nextGraphemeBoundary(str, col) {
  if (col < 0) col = 0;
  if (col >= str.length) return str.length;
  const segs = getGraphemeSegments(str);
  for (const s of segs) {
    if (s.index > col) {
      return s.index;
    }
  }
  return str.length;
}

/**
 * Check if a character is a word character
 * @param {string} char 
 * @returns {boolean}
 */
function isWordChar(char) {
  if (!char) return false;
  return /[\p{L}\p{N}_]/u.test(char);
}

/**
 * Check if a character is whitespace
 * @param {string} char 
 * @returns {boolean}
 */
function isWhitespace(char) {
  return char === ' ' || char === '\t' || char === '\n' || char === '\r';
}

/**
 * Find the previous word boundary before `col`
 * @param {string} str 
 * @param {number} col 
 * @returns {number}
 */
function prevWordBoundary(str, col) {
  if (col <= 0) return 0;
  let pos = col;

  // If pos is inside or at the end of whitespace, skip whitespace backwards
  while (pos > 0 && isWhitespace(str[pos - 1])) {
    pos = prevGraphemeBoundary(str, pos);
  }

  if (pos <= 0) return 0;

  // Determine type of character preceding pos
  const prevChar = str[pos - 1];
  const lookingForWord = isWordChar(prevChar);

  if (lookingForWord) {
    while (pos > 0 && isWordChar(str[pos - 1])) {
      pos = prevGraphemeBoundary(str, pos);
    }
  } else {
    // Non-word punctuation
    while (pos > 0 && !isWordChar(str[pos - 1]) && !isWhitespace(str[pos - 1])) {
      pos = prevGraphemeBoundary(str, pos);
    }
  }

  return pos;
}

/**
 * Find the next word boundary after `col`
 * @param {string} str 
 * @param {number} col 
 * @returns {number}
 */
function nextWordBoundary(str, col) {
  const len = str.length;
  if (col >= len) return len;
  let pos = col;

  const currChar = str[pos];
  if (isWhitespace(currChar)) {
    // Skip whitespace forward
    while (pos < len && isWhitespace(str[pos])) {
      pos = nextGraphemeBoundary(str, pos);
    }
  } else if (isWordChar(currChar)) {
    // Advance across word chars
    while (pos < len && isWordChar(str[pos])) {
      pos = nextGraphemeBoundary(str, pos);
    }
  } else {
    // Advance across punctuation
    while (pos < len && !isWordChar(str[pos]) && !isWhitespace(str[pos])) {
      pos = nextGraphemeBoundary(str, pos);
    }
  }

  return pos;
}

// Export for browser & node
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    getGraphemeSegments,
    prevGraphemeBoundary,
    nextGraphemeBoundary,
    isWordChar,
    isWhitespace,
    prevWordBoundary,
    nextWordBoundary
  };
}

