// Custom DOM-based Editing Surface for PatchPad

class PatchPadEditorView {
  constructor(containerElement, docModel, undoManager, options = {}) {
    this.container = containerElement;
    this.doc = docModel;
    this.undo = undoManager;
    this.options = options;

    // Selections array: each item is { anchor: {line, col}, head: {line, col} }
    this.selections = [{
      anchor: { line: 0, col: 0 },
      head: { line: 0, col: 0 }
    }];

    this.desiredCol = 0; // For vertical navigation across lines
    this.isDragging = false;
    this.isFocused = false;
    this.searchHighlights = []; // Array of matches
    this.activeSearchMatchIndex = -1;

    // Metrics
    this.lineHeight = 24;
    this.charWidth = 8.5; // Monospace approximate, measured dynamically
    this.gutterWidth = 50;

    this.onCursorChange = options.onCursorChange || null;
    this.onContentChange = options.onContentChange || null;
    this.onSaveRequest = options.onSaveRequest || null;
    this.onFindRequest = options.onFindRequest || null;
    this.onEscape = options.onEscape || null;

    this._initDom();
    this._measureFont();
    this._bindEvents();
    this.render();
  }

  _initDom() {
    this.container.innerHTML = '';
    this.container.classList.add('patchpad-editor-wrapper');

    // Hidden input capture for keyboard/clipboard events
    this.inputCapture = document.createElement('textarea');
    this.inputCapture.className = 'patchpad-input-capture';
    this.inputCapture.setAttribute('tabindex', '0');
    this.inputCapture.setAttribute('autocomplete', 'off');
    this.inputCapture.setAttribute('autocorrect', 'off');
    this.inputCapture.setAttribute('autocapitalize', 'off');
    this.inputCapture.setAttribute('spellcheck', 'false');
    this.container.appendChild(this.inputCapture);

    // Main scroll container
    this.scrollContainer = document.createElement('div');
    this.scrollContainer.className = 'patchpad-scroll-container';
    this.container.appendChild(this.scrollContainer);

    // Sizer sets full scroll height & width
    this.sizer = document.createElement('div');
    this.sizer.className = 'patchpad-sizer';
    this.scrollContainer.appendChild(this.sizer);

    // Layer container
    this.layersContainer = document.createElement('div');
    this.layersContainer.className = 'patchpad-layers-container';
    this.scrollContainer.appendChild(this.layersContainer);

    // Gutter
    this.gutter = document.createElement('div');
    this.gutter.className = 'patchpad-gutter';
    this.layersContainer.appendChild(this.gutter);

    // Content container (lines, selections, carets)
    this.contentContainer = document.createElement('div');
    this.contentContainer.className = 'patchpad-content';
    this.layersContainer.appendChild(this.contentContainer);

    // Sub-layers inside content
    this.searchHighlightsLayer = document.createElement('div');
    this.searchHighlightsLayer.className = 'patchpad-search-highlights-layer';
    this.contentContainer.appendChild(this.searchHighlightsLayer);

    this.selectionLayer = document.createElement('div');
    this.selectionLayer.className = 'patchpad-selection-layer';
    this.contentContainer.appendChild(this.selectionLayer);

    this.textLayer = document.createElement('div');
    this.textLayer.className = 'patchpad-text-layer';
    this.contentContainer.appendChild(this.textLayer);

    this.cursorLayer = document.createElement('div');
    this.cursorLayer.className = 'patchpad-cursor-layer';
    this.contentContainer.appendChild(this.cursorLayer);
  }

  _measureFont() {
    const testSpan = document.createElement('span');
    testSpan.className = 'patchpad-measure-span';
    testSpan.textContent = 'MMMMMMMMMM1234567890';
    this.textLayer.appendChild(testSpan);
    const rect = testSpan.getBoundingClientRect();
    if (rect.width > 0) {
      this.charWidth = rect.width / 20;
    }
    if (rect.height > 0) {
      this.lineHeight = rect.height;
    }
    testSpan.remove();

    // Setup canvas for subpixel text measurement
    const canvas = document.createElement('canvas');
    this.canvasCtx = canvas.getContext('2d');
    if (this.canvasCtx) {
      const style = window.getComputedStyle(this.container);
      this.canvasCtx.font = `${style.fontSize || '14px'} ${style.fontFamily || 'monospace'}`;
    }
  }

  measureTextWidth(str) {
    if (!str) return 0;
    if (this.canvasCtx) {
      return this.canvasCtx.measureText(str).width;
    }
    return str.length * this.charWidth;
  }

  colToX(lineIdx, col) {
    const line = this.doc.getLine(lineIdx);
    const sub = line.substring(0, col);
    return this.measureTextWidth(sub);
  }

  xToCol(lineIdx, x) {
    const line = this.doc.getLine(lineIdx);
    if (!line || x <= 0) return 0;

    const segs = getGraphemeSegments(line);
    if (segs.length === 0) return 0;

    let prevX = 0;
    let prevCol = 0;

    for (let i = 0; i < segs.length; i++) {
      const seg = segs[i];
      const col = seg.index + seg.segment.length;
      const curX = this.measureTextWidth(line.substring(0, col));
      const midX = (prevX + curX) / 2;

      if (x < midX) {
        return prevCol;
      }
      prevX = curX;
      prevCol = col;
    }

    return line.length;
  }

  posFromMouseEvent(e) {
    const rect = this.contentContainer.getBoundingClientRect();
    const clientX = e.clientX;
    const clientY = e.clientY;

    const relY = clientY - rect.top;
    const relX = clientX - rect.left;

    let lineIdx = Math.floor(relY / this.lineHeight);
    lineIdx = Math.max(0, Math.min(this.doc.getLineCount() - 1, lineIdx));

    const col = this.xToCol(lineIdx, Math.max(0, relX));
    return { line: lineIdx, col };
  }

  _bindEvents() {
    // Focus tracking
    this.container.addEventListener('mousedown', (e) => {
      this.focus();
    });

    this.inputCapture.addEventListener('focus', () => {
      this.isFocused = true;
      this.container.classList.add('focused');
      this.renderCarets();
    });

    this.inputCapture.addEventListener('blur', () => {
      this.isFocused = false;
      this.container.classList.remove('focused');
      this.renderCarets();
    });

    // Scrolling
    this.scrollContainer.addEventListener('scroll', () => {
      this.render();
    });

    // Mouse Selection & Caret handling
    this.scrollContainer.addEventListener('mousedown', (e) => {
      if (e.button !== 0) return; // Left click only
      this.focus();

      const pos = this.posFromMouseEvent(e);
      this.desiredCol = pos.col;

      if (e.altKey || ((e.ctrlKey || e.metaKey) && !e.shiftKey)) {
        // Add multi-caret
        this.selections.push({
          anchor: { ...pos },
          head: { ...pos }
        });
      } else if (e.shiftKey) {
        // Extend primary selection
        if (this.selections.length === 0) {
          this.selections = [{ anchor: { ...pos }, head: { ...pos } }];
        } else {
          this.selections[this.selections.length - 1].head = { ...pos };
        }
      } else {
        // Single caret
        if (e.detail === 2) {
          // Double click: select word
          const wordRange = this.doc.getWordAtPos(pos);
          this.selections = [{
            anchor: wordRange.start,
            head: wordRange.end
          }];
        } else if (e.detail >= 3) {
          // Triple click: select line
          const lineSel = this.doc.getLineSelection(pos.line);
          this.selections = [lineSel];
        } else {
          this.selections = [{
            anchor: { ...pos },
            head: { ...pos }
          }];
        }
      }

      this.isDragging = true;
      this.render();
      this._emitCursorChange();

      const onMouseMove = (moveEvent) => {
        if (!this.isDragging) return;
        const curPos = this.posFromMouseEvent(moveEvent);
        this.desiredCol = curPos.col;
        const primary = this.selections[this.selections.length - 1];
        primary.head = { ...curPos };
        this._autoScroll(moveEvent);
        this.render();
        this._emitCursorChange();
      };

      const onMouseUp = () => {
        this.isDragging = false;
        window.removeEventListener('mousemove', onMouseMove);
        window.removeEventListener('mouseup', onMouseUp);
      };

      window.addEventListener('mousemove', onMouseMove);
      window.addEventListener('mouseup', onMouseUp);
    });

    // Keyboard handling
    this.inputCapture.addEventListener('keydown', (e) => this._handleKeyDown(e));
    this.inputCapture.addEventListener('beforeinput', (e) => this._handleBeforeInput(e));
    this.inputCapture.addEventListener('copy', (e) => this._handleCopy(e));
    this.inputCapture.addEventListener('cut', (e) => this._handleCut(e));
    this.inputCapture.addEventListener('paste', (e) => this._handlePaste(e));
  }

  _autoScroll(e) {
    const rect = this.scrollContainer.getBoundingClientRect();
    const margin = 20;
    if (e.clientY < rect.top + margin) {
      this.scrollContainer.scrollTop -= 15;
    } else if (e.clientY > rect.bottom - margin) {
      this.scrollContainer.scrollTop += 15;
    }
    if (e.clientX < rect.left + margin) {
      this.scrollContainer.scrollLeft -= 15;
    } else if (e.clientX > rect.right - margin) {
      this.scrollContainer.scrollLeft += 15;
    }
  }

  focus() {
    if (document.activeElement !== this.inputCapture) {
      this.inputCapture.focus();
    }
  }

  _emitCursorChange() {
    if (this.onCursorChange) {
      const primary = this.getPrimarySelection();
      this.onCursorChange({
        line: primary.head.line + 1,
        col: primary.head.col + 1,
        selectedText: this.doc.getSelectedText(primary),
        caretCount: this.selections.length,
        hasSelection: !this.doc.normalizeSelection(primary).isCollapsed
      });
    }
  }

  _emitContentChange(type = 'edit') {
    if (this.onContentChange) {
      this.onContentChange(this.doc.getText(), type);
    }
  }

  getPrimarySelection() {
    return this.selections[this.selections.length - 1] || {
      anchor: { line: 0, col: 0 },
      head: { line: 0, col: 0 }
    };
  }

  setSelections(sels) {
    this.selections = sels.map(s => ({
      anchor: this.doc.clampPosition(s.anchor),
      head: this.doc.clampPosition(s.head)
    }));
    this.render();
    this._emitCursorChange();
    this.scrollToCursor();
  }

  setSearchHighlights(matches, activeIndex = -1) {
    this.searchHighlights = matches || [];
    this.activeSearchMatchIndex = activeIndex;
    this.renderSearchHighlights();
  }

  scrollToCursor() {
    const primary = this.getPrimarySelection();
    const top = primary.head.line * this.lineHeight;
    const bottom = top + this.lineHeight;
    const left = this.colToX(primary.head.line, primary.head.col);
    const right = left + 20;

    const scrollTop = this.scrollContainer.scrollTop;
    const scrollLeft = this.scrollContainer.scrollLeft;
    const viewHeight = this.scrollContainer.clientHeight;
    const viewWidth = this.scrollContainer.clientWidth;

    if (top < scrollTop) {
      this.scrollContainer.scrollTop = top;
    } else if (bottom > scrollTop + viewHeight) {
      this.scrollContainer.scrollTop = bottom - viewHeight;
    }

    if (left < scrollLeft) {
      this.scrollContainer.scrollLeft = left;
    } else if (right > scrollLeft + viewWidth) {
      this.scrollContainer.scrollLeft = right - viewWidth;
    }
  }

  _handleBeforeInput(e) {
    if (e.inputType === 'insertText' && e.data) {
      e.preventDefault();
      this.insertTextAtCarets(e.data, 'typing');
    }
  }

  _handleKeyDown(e) {
    const isMac = navigator.platform.toUpperCase().indexOf('MAC') >= 0;
    const ctrlOrCmd = isMac ? e.metaKey : e.ctrlKey;

    // Shortcuts
    if (ctrlOrCmd && !e.altKey && !e.shiftKey) {
      if (e.key === 's' || e.key === 'S') {
        e.preventDefault();
        if (this.onSaveRequest) this.onSaveRequest();
        return;
      }
      if (e.key === 'f' || e.key === 'F') {
        e.preventDefault();
        if (this.onFindRequest) this.onFindRequest();
        return;
      }
      if (e.key === 'z' || e.key === 'Z') {
        e.preventDefault();
        this.performUndo();
        return;
      }
      if (e.key === 'y' || e.key === 'Y') {
        e.preventDefault();
        this.performRedo();
        return;
      }
      if (e.key === 'a' || e.key === 'A') {
        e.preventDefault();
        this.selectAll();
        return;
      }
    }

    if (ctrlOrCmd && e.shiftKey && (e.key === 'z' || e.key === 'Z')) {
      e.preventDefault();
      this.performRedo();
      return;
    }

    // Escape
    if (e.key === 'Escape') {
      e.preventDefault();
      if (this.onEscape) this.onEscape();
      return;
    }

    // Tab / Shift+Tab (Indentation)
    if (e.key === 'Tab') {
      e.preventDefault();
      if (e.shiftKey) {
        this.outdent();
      } else {
        this.indent();
      }
      return;
    }

    // Enter / Newline
    if (e.key === 'Enter') {
      e.preventDefault();
      this.insertNewline();
      return;
    }

    // Backspace
    if (e.key === 'Backspace') {
      e.preventDefault();
      this.deleteBackward(ctrlOrCmd || e.altKey);
      return;
    }

    // Delete
    if (e.key === 'Delete') {
      e.preventDefault();
      this.deleteForward(ctrlOrCmd || e.altKey);
      return;
    }

    // Navigation Keys
    if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End', 'PageUp', 'PageDown'].includes(e.key)) {
      e.preventDefault();
      this._handleNavigation(e.key, e.shiftKey, ctrlOrCmd || e.altKey, ctrlOrCmd);
      return;
    }

    // Normal Character Insertion fallback (if beforeinput not fired)
    if (!ctrlOrCmd && !e.altKey && e.key.length === 1) {
      e.preventDefault();
      this.insertTextAtCarets(e.key, 'typing');
    }
  }

  _handleNavigation(key, isShift, isWordMod, isDocMod) {
    const isMac = navigator.platform.toUpperCase().indexOf('MAC') >= 0;

    this.selections = this.selections.map(sel => {
      let head = { ...sel.head };
      let anchor = isShift ? { ...sel.anchor } : { ...head };

      switch (key) {
        case 'ArrowLeft': {
          if (!isShift && !this.doc.isPositionsEqual(sel.anchor, sel.head)) {
            // Collapse to start of selection
            const norm = this.doc.normalizeSelection(sel);
            head = { ...norm.start };
            anchor = { ...head };
          } else if (isWordMod) {
            head = this.doc.getPrevWordPos(head);
            if (!isShift) anchor = { ...head };
          } else {
            head = this.doc.getPrevGraphemePos(head);
            if (!isShift) anchor = { ...head };
          }
          this.desiredCol = head.col;
          break;
        }
        case 'ArrowRight': {
          if (!isShift && !this.doc.isPositionsEqual(sel.anchor, sel.head)) {
            // Collapse to end of selection
            const norm = this.doc.normalizeSelection(sel);
            head = { ...norm.end };
            anchor = { ...head };
          } else if (isWordMod) {
            head = this.doc.getNextWordPos(head);
            if (!isShift) anchor = { ...head };
          } else {
            head = this.doc.getNextGraphemePos(head);
            if (!isShift) anchor = { ...head };
          }
          this.desiredCol = head.col;
          break;
        }
        case 'ArrowUp': {
          if (isDocMod) {
            head = { line: 0, col: 0 };
          } else if (head.line > 0) {
            const targetLine = head.line - 1;
            const col = Math.min(this.doc.getLineLength(targetLine), this.desiredCol);
            head = { line: targetLine, col };
          } else {
            head = { line: 0, col: 0 };
          }
          if (!isShift) anchor = { ...head };
          break;
        }
        case 'ArrowDown': {
          if (isDocMod) {
            const lastLine = this.doc.getLineCount() - 1;
            head = { line: lastLine, col: this.doc.getLineLength(lastLine) };
          } else if (head.line < this.doc.getLineCount() - 1) {
            const targetLine = head.line + 1;
            const col = Math.min(this.doc.getLineLength(targetLine), this.desiredCol);
            head = { line: targetLine, col };
          } else {
            const lastLine = this.doc.getLineCount() - 1;
            head = { line: lastLine, col: this.doc.getLineLength(lastLine) };
          }
          if (!isShift) anchor = { ...head };
          break;
        }
        case 'Home': {
          if (isDocMod) {
            head = { line: 0, col: 0 };
          } else {
            head = { line: head.line, col: 0 };
          }
          this.desiredCol = head.col;
          if (!isShift) anchor = { ...head };
          break;
        }
        case 'End': {
          if (isDocMod) {
            const lastLine = this.doc.getLineCount() - 1;
            head = { line: lastLine, col: this.doc.getLineLength(lastLine) };
          } else {
            head = { line: head.line, col: this.doc.getLineLength(head.line) };
          }
          this.desiredCol = head.col;
          if (!isShift) anchor = { ...head };
          break;
        }
        case 'PageUp': {
          const jump = Math.max(1, Math.floor(this.scrollContainer.clientHeight / this.lineHeight));
          const targetLine = Math.max(0, head.line - jump);
          head = { line: targetLine, col: Math.min(this.doc.getLineLength(targetLine), this.desiredCol) };
          if (!isShift) anchor = { ...head };
          break;
        }
        case 'PageDown': {
          const jump = Math.max(1, Math.floor(this.scrollContainer.clientHeight / this.lineHeight));
          const lastLine = this.doc.getLineCount() - 1;
          const targetLine = Math.min(lastLine, head.line + jump);
          head = { line: targetLine, col: Math.min(this.doc.getLineLength(targetLine), this.desiredCol) };
          if (!isShift) anchor = { ...head };
          break;
        }
      }

      return { anchor, head };
    });

    this.render();
    this._emitCursorChange();
    this.scrollToCursor();
  }

  selectAll() {
    const lastLine = this.doc.getLineCount() - 1;
    this.selections = [{
      anchor: { line: 0, col: 0 },
      head: { line: lastLine, col: this.doc.getLineLength(lastLine) }
    }];
    this.render();
    this._emitCursorChange();
  }

  _handleCopy(e) {
    const textToCopy = this.selections.map(s => this.doc.getSelectedText(s)).filter(Boolean).join('\n');
    if (textToCopy) {
      e.clipboardData.setData('text/plain', textToCopy);
      e.preventDefault();
    }
  }

  _handleCut(e) {
    const textToCopy = this.selections.map(s => this.doc.getSelectedText(s)).filter(Boolean).join('\n');
    if (textToCopy) {
      e.clipboardData.setData('text/plain', textToCopy);
      this.deleteBackward(false);
      e.preventDefault();
    }
  }

  _handlePaste(e) {
    const pasted = e.clipboardData.getData('text/plain');
    if (pasted) {
      e.preventDefault();
      this.insertTextAtCarets(pasted, 'paste');
    }
  }

  insertTextAtCarets(text, type = 'typing') {
    const beforeText = this.doc.getText();
    const beforeSelections = JSON.parse(JSON.stringify(this.selections));

    // Sort selections descending by start position to apply edits without shifting coordinates
    const sorted = this.selections.map((sel, idx) => ({ sel, idx, norm: this.doc.normalizeSelection(sel) }))
      .sort((a, b) => this.doc.comparePositions(b.norm.start, a.norm.start));

    const newSelectionsMap = [];

    for (const item of sorted) {
      const res = this.doc.replaceRange(item.norm.start, item.norm.end, text);
      newSelectionsMap[item.idx] = {
        anchor: res.newEndPos,
        head: res.newEndPos
      };
    }

    const afterText = this.doc.getText();
    this.selections = newSelectionsMap;
    this.desiredCol = this.getPrimarySelection().head.col;

    this.undo.recordAction({
      beforeText,
      afterText,
      beforeSelections,
      afterSelections: this.selections,
      type
    });

    this.render();
    this._emitCursorChange();
    this._emitContentChange(type);
    this.scrollToCursor();
  }

  insertNewline() {
    this.insertTextAtCarets('\n', 'typing');
  }

  deleteBackward(isWord = false) {
    const beforeText = this.doc.getText();
    const beforeSelections = JSON.parse(JSON.stringify(this.selections));

    const sorted = this.selections.map((sel, idx) => ({ sel, idx, norm: this.doc.normalizeSelection(sel) }))
      .sort((a, b) => this.doc.comparePositions(b.norm.start, a.norm.start));

    const newSelectionsMap = [];

    for (const item of sorted) {
      let startPos, endPos;
      if (!item.norm.isCollapsed) {
        startPos = item.norm.start;
        endPos = item.norm.end;
      } else {
        endPos = item.norm.head;
        if (isWord) {
          startPos = this.doc.getPrevWordPos(endPos);
        } else {
          startPos = this.doc.getPrevGraphemePos(endPos);
        }
      }

      const res = this.doc.replaceRange(startPos, endPos, '');
      newSelectionsMap[item.idx] = {
        anchor: res.newEndPos,
        head: res.newEndPos
      };
    }

    const afterText = this.doc.getText();
    this.selections = newSelectionsMap;
    this.desiredCol = this.getPrimarySelection().head.col;

    this.undo.recordAction({
      beforeText,
      afterText,
      beforeSelections,
      afterSelections: this.selections,
      type: 'backspace'
    });

    this.render();
    this._emitCursorChange();
    this._emitContentChange('delete');
    this.scrollToCursor();
  }

  deleteForward(isWord = false) {
    const beforeText = this.doc.getText();
    const beforeSelections = JSON.parse(JSON.stringify(this.selections));

    const sorted = this.selections.map((sel, idx) => ({ sel, idx, norm: this.doc.normalizeSelection(sel) }))
      .sort((a, b) => this.doc.comparePositions(b.norm.start, a.norm.start));

    const newSelectionsMap = [];

    for (const item of sorted) {
      let startPos, endPos;
      if (!item.norm.isCollapsed) {
        startPos = item.norm.start;
        endPos = item.norm.end;
      } else {
        startPos = item.norm.head;
        if (isWord) {
          endPos = this.doc.getNextWordPos(startPos);
        } else {
          endPos = this.doc.getNextGraphemePos(startPos);
        }
      }

      const res = this.doc.replaceRange(startPos, endPos, '');
      newSelectionsMap[item.idx] = {
        anchor: res.newEndPos,
        head: res.newEndPos
      };
    }

    const afterText = this.doc.getText();
    this.selections = newSelectionsMap;
    this.desiredCol = this.getPrimarySelection().head.col;

    this.undo.recordAction({
      beforeText,
      afterText,
      beforeSelections,
      afterSelections: this.selections,
      type: 'delete'
    });

    this.render();
    this._emitCursorChange();
    this._emitContentChange('delete');
    this.scrollToCursor();
  }

  indent() {
    const primary = this.getPrimarySelection();
    const norm = this.doc.normalizeSelection(primary);

    // Multiline selection block indent
    if (!norm.isCollapsed && (norm.start.line !== norm.end.line || (norm.start.col === 0 && norm.end.col === this.doc.getLineLength(norm.end.line)))) {
      const beforeText = this.doc.getText();
      const beforeSelections = JSON.parse(JSON.stringify(this.selections));

      const res = this.doc.indentBlock(primary);
      this.selections = [res.selection];

      const afterText = this.doc.getText();
      this.undo.recordAction({
        beforeText,
        afterText,
        beforeSelections,
        afterSelections: this.selections,
        type: 'indent'
      });

      this.render();
      this._emitCursorChange();
      this._emitContentChange('indent');
      return;
    }

    // Single line or collapsed cursor: insert 2 spaces
    this.insertTextAtCarets('  ', 'indent');
  }

  outdent() {
    const primary = this.getPrimarySelection();
    const beforeText = this.doc.getText();
    const beforeSelections = JSON.parse(JSON.stringify(this.selections));

    const res = this.doc.outdentBlock(primary);
    this.selections = [res.selection];

    const afterText = this.doc.getText();
    this.undo.recordAction({
      beforeText,
      afterText,
      beforeSelections,
      afterSelections: this.selections,
      type: 'outdent'
    });

    this.render();
    this._emitCursorChange();
    this._emitContentChange('outdent');
  }

  performUndo() {
    const res = this.undo.undo();
    if (!res) return;
    this.doc.setText(res.text);
    this.selections = res.selections || [{ anchor: { line: 0, col: 0 }, head: { line: 0, col: 0 } }];
    this.render();
    this._emitCursorChange();
    this._emitContentChange('undo');
    this.scrollToCursor();
  }

  performRedo() {
    const res = this.undo.redo();
    if (!res) return;
    this.doc.setText(res.text);
    this.selections = res.selections || [{ anchor: { line: 0, col: 0 }, head: { line: 0, col: 0 } }];
    this.render();
    this._emitCursorChange();
    this._emitContentChange('redo');
    this.scrollToCursor();
  }

  // Virtualized DOM Rendering
  render() {
    const lineCount = this.doc.getLineCount();
    const totalHeight = lineCount * this.lineHeight;

    // Estimate max width
    let maxLen = 0;
    for (let i = 0; i < Math.min(lineCount, 500); i++) {
      if (this.doc.lines[i].length > maxLen) maxLen = this.doc.lines[i].length;
    }
    const totalWidth = Math.max(800, maxLen * this.charWidth + 100);

    this.sizer.style.height = `${totalHeight}px`;
    this.sizer.style.width = `${totalWidth}px`;

    const scrollTop = this.scrollContainer.scrollTop;
    const viewportHeight = this.scrollContainer.clientHeight || 600;

    const overscan = 15;
    const startLine = Math.max(0, Math.floor(scrollTop / this.lineHeight) - overscan);
    const endLine = Math.min(lineCount - 1, Math.ceil((scrollTop + viewportHeight) / this.lineHeight) + overscan);

    this.layersContainer.style.top = `${startLine * this.lineHeight}px`;

    // Render Gutter
    let gutterHtml = '';
    const activeLine = this.getPrimarySelection().head.line;
    for (let i = startLine; i <= endLine; i++) {
      const isActive = i === activeLine ? ' active' : '';
      gutterHtml += `<div class="patchpad-gutter-line${isActive}" style="height:${this.lineHeight}px">${i + 1}</div>`;
    }
    this.gutter.innerHTML = gutterHtml;

    // Render Text Lines
    let linesHtml = '';
    for (let i = startLine; i <= endLine; i++) {
      const lineText = this.doc.getLine(i);
      const escaped = this._escapeHtml(lineText);
      linesHtml += `<div class="patchpad-line" style="height:${this.lineHeight}px">${escaped || '&nbsp;'}</div>`;
    }
    this.textLayer.innerHTML = linesHtml;

    // Render Selection, Highlights & Carets
    this.renderSelections(startLine, endLine);
    this.renderSearchHighlights(startLine, endLine);
    this.renderCarets(startLine, endLine);
  }

  _escapeHtml(str) {
    if (!str) return '';
    return str
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  renderSelections(startLine, endLine) {
    if (startLine === undefined) {
      const scrollTop = this.scrollContainer.scrollTop;
      const viewportHeight = this.scrollContainer.clientHeight || 600;
      startLine = Math.max(0, Math.floor(scrollTop / this.lineHeight) - 15);
      endLine = Math.min(this.doc.getLineCount() - 1, Math.ceil((scrollTop + viewportHeight) / this.lineHeight) + 15);
    }

    let selHtml = '';
    for (const sel of this.selections) {
      const norm = this.doc.normalizeSelection(sel);
      if (norm.isCollapsed) continue;

      const sL = Math.max(startLine, norm.start.line);
      const eL = Math.min(endLine, norm.end.line);

      for (let L = sL; L <= eL; L++) {
        const top = (L - startLine) * this.lineHeight;
        let leftCol = 0;
        let rightCol = this.doc.getLineLength(L);

        if (L === norm.start.line) leftCol = norm.start.col;
        if (L === norm.end.line) rightCol = norm.end.col;

        const leftX = this.colToX(L, leftCol);
        const rightX = this.colToX(L, rightCol);
        let width = Math.max(4, rightX - leftX);

        if (L < norm.end.line && rightCol === this.doc.getLineLength(L)) {
          width += 8; // Highlight newline span
        }

        selHtml += `<div class="patchpad-selection-rect" style="top:${top}px;left:${leftX}px;width:${width}px;height:${this.lineHeight}px"></div>`;
      }
    }
    this.selectionLayer.innerHTML = selHtml;
  }

  renderSearchHighlights(startLine, endLine) {
    if (startLine === undefined) {
      const scrollTop = this.scrollContainer.scrollTop;
      const viewportHeight = this.scrollContainer.clientHeight || 600;
      startLine = Math.max(0, Math.floor(scrollTop / this.lineHeight) - 15);
      endLine = Math.min(this.doc.getLineCount() - 1, Math.ceil((scrollTop + viewportHeight) / this.lineHeight) + 15);
    }

    let hlHtml = '';
    for (let i = 0; i < this.searchHighlights.length; i++) {
      const match = this.searchHighlights[i];
      if (match.end.line < startLine || match.start.line > endLine) continue;

      const isActive = i === this.activeSearchMatchIndex ? ' active-match' : '';
      const sL = Math.max(startLine, match.start.line);
      const eL = Math.min(endLine, match.end.line);

      for (let L = sL; L <= eL; L++) {
        const top = (L - startLine) * this.lineHeight;
        let leftCol = (L === match.start.line) ? match.start.col : 0;
        let rightCol = (L === match.end.line) ? match.end.col : this.doc.getLineLength(L);

        const leftX = this.colToX(L, leftCol);
        const rightX = this.colToX(L, rightCol);
        const width = Math.max(2, rightX - leftX);

        hlHtml += `<div class="patchpad-search-rect${isActive}" style="top:${top}px;left:${leftX}px;width:${width}px;height:${this.lineHeight}px"></div>`;
      }
    }
    this.searchHighlightsLayer.innerHTML = hlHtml;
  }

  renderCarets(startLine, endLine) {
    if (startLine === undefined) {
      const scrollTop = this.scrollContainer.scrollTop;
      const viewportHeight = this.scrollContainer.clientHeight || 600;
      startLine = Math.max(0, Math.floor(scrollTop / this.lineHeight) - 15);
      endLine = Math.min(this.doc.getLineCount() - 1, Math.ceil((scrollTop + viewportHeight) / this.lineHeight) + 15);
    }

    let caretHtml = '';
    for (const sel of this.selections) {
      const head = sel.head;
      if (head.line >= startLine && head.line <= endLine) {
        const top = (head.line - startLine) * this.lineHeight;
        const left = this.colToX(head.line, head.col);
        const blinkClass = this.isFocused ? ' blinking' : '';
        caretHtml += `<div class="patchpad-caret${blinkClass}" style="top:${top}px;left:${left}px;height:${this.lineHeight}px"></div>`;
      }
    }
    this.cursorLayer.innerHTML = caretHtml;
  }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { PatchPadEditorView };
}

// API client for PatchPad backend

const Api = {
  async listReports() {
    const res = await fetch('/api/reports');
    if (!res.ok) throw new Error(`Failed to list reports: ${res.statusText}`);
    return await res.json();
  },

  async getReport(id) {
    const res = await fetch(`/api/reports/${encodeURIComponent(id)}`);
    if (!res.ok) {
      const errData = await res.json().catch(() => ({}));
      const err = new Error(errData.error || `Failed to fetch report: ${res.statusText}`);
      err.status = res.status;
      throw err;
    }
    return await res.json();
  },

  async saveReport(id, baseRevision, content, comment = '') {
    const res = await fetch(`/api/reports/${encodeURIComponent(id)}/save`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        documentId: id,
        baseRevision,
        content,
        comment
      })
    });

    const data = await res.json().catch(() => ({}));

    if (!res.ok) {
      const err = new Error(data.error || `Save failed: ${res.statusText}`);
      err.status = res.status;
      err.serverRevision = data.serverRevision;
      throw err;
    }

    return data;
  },

  async listRevisions(id) {
    const res = await fetch(`/api/reports/${encodeURIComponent(id)}/revisions`);
    if (!res.ok) throw new Error(`Failed to list revisions: ${res.statusText}`);
    return await res.json();
  },

  async getRevisionContent(id, revNum) {
    const res = await fetch(`/api/reports/${encodeURIComponent(id)}/revisions/${revNum}`);
    if (!res.ok) throw new Error(`Failed to fetch revision: ${res.statusText}`);
    return await res.json();
  }
};

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { Api };
}

// Main Application Controller for PatchPad

document.addEventListener('DOMContentLoaded', async () => {
  const state = {
    currentDocId: 'incident-alpha',
    docMetadata: null,
    baseRevision: 1,
    lastSavedContent: '',
    reportsList: [],
    isDirty: false,
    previewRevision: null
  };

  // UI Elements
  const el = {
    // Header & Document Info
    docTitle: document.getElementById('doc-title'),
    docAuthor: document.getElementById('doc-author'),
    reportSelect: document.getElementById('report-select'),

    // Toolbar Buttons
    btnSave: document.getElementById('btn-save'),
    btnUndo: document.getElementById('btn-undo'),
    btnRedo: document.getElementById('btn-redo'),
    btnFind: document.getElementById('btn-find'),
    btnHistory: document.getElementById('btn-history'),
    saveBadge: document.getElementById('save-badge'),

    // Find & Replace Panel
    findPanel: document.getElementById('find-panel'),
    findInput: document.getElementById('find-input'),
    replaceInput: document.getElementById('replace-input'),
    matchCount: document.getElementById('match-count'),
    btnFindPrev: document.getElementById('btn-find-prev'),
    btnFindNext: document.getElementById('btn-find-next'),
    btnReplaceCurrent: document.getElementById('btn-replace-current'),
    btnReplaceAll: document.getElementById('btn-replace-all'),
    btnCloseFind: document.getElementById('btn-close-find'),
    caseSensitiveCheckbox: document.getElementById('find-case-sensitive'),

    // Editor Container
    editorContainer: document.getElementById('editor-container'),

    // Revision History Sidebar
    historySidebar: document.getElementById('history-sidebar'),
    historyList: document.getElementById('history-list'),
    btnCloseHistory: document.getElementById('btn-close-history'),

    // Status Bar
    statusCursor: document.getElementById('status-cursor'),
    statusStats: document.getElementById('status-stats'),
    statusRevision: document.getElementById('status-revision'),
    statusSaveState: document.getElementById('status-save-state'),

    // Modals
    previewModal: document.getElementById('preview-modal'),
    previewTitle: document.getElementById('preview-title'),
    previewMeta: document.getElementById('preview-meta'),
    previewContent: document.getElementById('preview-content'),
    btnRestorePreview: document.getElementById('btn-restore-preview'),
    btnClosePreview: document.getElementById('btn-close-preview'),

    conflictModal: document.getElementById('conflict-modal'),
    conflictMessage: document.getElementById('conflict-message'),
    btnConflictKeep: document.getElementById('btn-conflict-keep'),
    btnConflictPreview: document.getElementById('btn-conflict-preview'),
    btnConflictReload: document.getElementById('btn-conflict-reload'),

    // Toast Container
    toastContainer: document.getElementById('toast-container')
  };

  // Toast notification helper
  function showToast(message, type = 'info', duration = 3500) {
    const toast = document.createElement('div');
    toast.className = `patchpad-toast toast-${type}`;
    toast.innerHTML = `<span class="toast-text">${message}</span>`;
    el.toastContainer.appendChild(toast);
    setTimeout(() => {
      toast.classList.add('show');
    }, 10);
    setTimeout(() => {
      toast.classList.remove('show');
      setTimeout(() => toast.remove(), 300);
    }, duration);
  }

  // Initialize Core Models
  const docModel = new DocumentModel('');
  const undoManager = new UndoManager();
  const findEngine = new FindReplaceEngine();

  // Initialize Custom Editor View
  const editorView = new PatchPadEditorView(el.editorContainer, docModel, undoManager, {
    onCursorChange: (info) => {
      if (info.caretCount > 1) {
        el.statusCursor.textContent = `${info.caretCount} carets (Primary Ln ${info.line}, Col ${info.col})`;
      } else if (info.hasSelection) {
        const charCount = info.selectedText.length;
        el.statusCursor.textContent = `Ln ${info.line}, Col ${info.col} (${charCount} selected)`;
      } else {
        el.statusCursor.textContent = `Ln ${info.line}, Col ${info.col}`;
      }
    },
    onContentChange: (text, type) => {
      updateDirtyState();
      updateDocumentStats();
      if (findEngine.query) {
        updateFindMatches();
      }
    },
    onSaveRequest: () => {
      saveCurrentReport();
    },
    onFindRequest: () => {
      toggleFindPanel(true);
    },
    onEscape: () => {
      // Escape from editing area focuses Find input
      if (!el.findPanel.classList.contains('hidden')) {
        el.findInput.focus();
        el.findInput.select();
      } else {
        toggleFindPanel(true);
      }
    }
  });

  // Undo/Redo button status listener
  undoManager.setOnChange(({ canUndo, canRedo }) => {
    el.btnUndo.disabled = !canUndo;
    el.btnRedo.disabled = !canRedo;
  });

  function updateDocumentStats() {
    const lineCount = docModel.getLineCount();
    const charCount = docModel.getText().length;
    el.statusStats.textContent = `${lineCount.toLocaleString()} lines, ${charCount.toLocaleString()} characters`;
  }

  function updateDirtyState() {
    const currentText = docModel.getText();
    const isDirty = currentText !== state.lastSavedContent;
    state.isDirty = isDirty;

    if (isDirty) {
      el.saveBadge.textContent = 'Unsaved changes';
      el.saveBadge.className = 'status-badge badge-unsaved';
      el.statusSaveState.textContent = '● Unsaved changes';
      el.statusSaveState.className = 'status-unsaved';
    } else {
      el.saveBadge.textContent = 'Saved';
      el.saveBadge.className = 'status-badge badge-saved';
      el.statusSaveState.textContent = '✓ Saved';
      el.statusSaveState.className = 'status-saved';
    }
  }

  // Load Document from Server
  async function loadDocument(id) {
    try {
      const doc = await Api.getReport(id);
      state.currentDocId = doc.id;
      state.docMetadata = doc;
      state.baseRevision = doc.current_revision;
      state.lastSavedContent = doc.content;

      // Update Header
      el.docTitle.textContent = doc.title;
      el.docAuthor.textContent = doc.author ? `Author: ${doc.author}` : '';
      el.statusRevision.textContent = `Revision ${doc.current_revision}`;

      // Update Editor
      docModel.setText(doc.content);
      undoManager.clear();
      editorView.setSelections([{ anchor: { line: 0, col: 0 }, head: { line: 0, col: 0 } }]);
      editorView.render();

      updateDirtyState();
      updateDocumentStats();
      refreshRevisionsList();

      showToast(`Loaded "${doc.title}" (Rev ${doc.current_revision})`, 'info', 2000);
    } catch (err) {
      console.error('Failed to load report:', err);
      showToast(`Error loading report: ${err.message}`, 'error', 5000);
    }
  }

  // Load Reports List
  async function loadReportsList() {
    try {
      const reports = await Api.listReports();
      state.reportsList = reports;
      el.reportSelect.innerHTML = '';
      for (const r of reports) {
        const opt = document.createElement('option');
        opt.value = r.id;
        opt.textContent = `${r.title} (${r.author || 'Unknown'})`;
        if (r.id === state.currentDocId) {
          opt.selected = true;
        }
        el.reportSelect.appendChild(opt);
      }
    } catch (err) {
      console.error('Failed to load reports list:', err);
    }
  }

  // Save Report
  async function saveCurrentReport() {
    const currentText = docModel.getText();

    if (!state.isDirty) {
      showToast('Document is already up to date (no changes to save)', 'info', 2500);
      return;
    }

    el.btnSave.disabled = true;
    el.saveBadge.textContent = 'Saving...';
    el.saveBadge.className = 'status-badge badge-saving';
    el.statusSaveState.textContent = '⟳ Saving...';

    try {
      const res = await Api.saveReport(
        state.currentDocId,
        state.baseRevision,
        currentText,
        'Saved from PatchPad editor'
      );

      if (res.saved) {
        state.baseRevision = res.revision;
        state.lastSavedContent = currentText;
        el.statusRevision.textContent = `Revision ${res.revision}`;
        updateDirtyState();
        refreshRevisionsList();
        showToast(`Report saved successfully as Revision ${res.revision}`, 'success');
      } else {
        updateDirtyState();
        showToast('Document unchanged', 'info');
      }
    } catch (err) {
      if (err.status === 409) {
        // Save conflict
        el.saveBadge.textContent = 'Conflict';
        el.saveBadge.className = 'status-badge badge-conflict';
        el.statusSaveState.textContent = '⚠ Conflict';
        el.statusSaveState.className = 'status-conflict';

        el.conflictMessage.innerHTML = `
          Another user or browser tab saved a newer version of this report (<strong>Revision ${err.serverRevision || 'newer'}</strong>).<br><br>
          Your current unsaved edits have been preserved in the editor. Choose an action below:
        `;
        el.conflictModal.classList.remove('hidden');
      } else {
        showToast(`Save failed: ${err.message}`, 'error', 5000);
        updateDirtyState();
      }
    } finally {
      el.btnSave.disabled = false;
    }
  }

  // Revision History
  async function refreshRevisionsList() {
    try {
      const revs = await Api.listRevisions(state.currentDocId);
      el.historyList.innerHTML = '';

      for (const r of revs) {
        const item = document.createElement('div');
        item.className = 'history-item';
        if (r.revision_number === state.baseRevision) {
          item.classList.add('current-revision');
        }

        const dateStr = new Date(r.created_at).toLocaleString();
        item.innerHTML = `
          <div class="history-item-header">
            <span class="history-rev-badge">Rev ${r.revision_number}</span>
            ${r.revision_number === state.baseRevision ? '<span class="history-current-tag">Current Base</span>' : ''}
          </div>
          <div class="history-item-meta">
            <span class="history-date">${dateStr}</span>
            <span class="history-chars">${(r.char_count || 0).toLocaleString()} chars</span>
          </div>
          ${r.comment ? `<div class="history-comment">${r.comment}</div>` : ''}
          <div class="history-item-actions">
            <button class="btn btn-sm btn-secondary btn-preview-rev" data-rev="${r.revision_number}">Preview</button>
            <button class="btn btn-sm btn-primary btn-restore-rev" data-rev="${r.revision_number}">Restore</button>
          </div>
        `;
        el.historyList.appendChild(item);
      }

      // Bind Preview and Restore buttons
      el.historyList.querySelectorAll('.btn-preview-rev').forEach(btn => {
        btn.addEventListener('click', () => {
          const revNum = parseInt(btn.dataset.rev, 10);
          previewRevision(revNum);
        });
      });

      el.historyList.querySelectorAll('.btn-restore-rev').forEach(btn => {
        btn.addEventListener('click', () => {
          const revNum = parseInt(btn.dataset.rev, 10);
          restoreRevision(revNum);
        });
      });
    } catch (err) {
      console.error('Failed to load revisions:', err);
    }
  }

  async function previewRevision(revNum) {
    try {
      const rev = await Api.getRevisionContent(state.currentDocId, revNum);
      state.previewRevision = rev;

      el.previewTitle.textContent = `Preview: ${state.docMetadata?.title || 'Report'} (Revision ${revNum})`;
      el.previewMeta.textContent = `Saved on ${new Date(rev.created_at).toLocaleString()} · ${rev.content.length.toLocaleString()} characters`;

      // Render line-numbered preview
      const lines = rev.content.split('\n');
      let previewHtml = '<div class="preview-line-container">';
      for (let i = 0; i < lines.length; i++) {
        const escaped = editorView._escapeHtml(lines[i]);
        previewHtml += `
          <div class="preview-line">
            <span class="preview-line-num">${i + 1}</span>
            <span class="preview-line-text">${escaped || '&nbsp;'}</span>
          </div>
        `;
      }
      previewHtml += '</div>';
      el.previewContent.innerHTML = previewHtml;

      el.previewModal.classList.remove('hidden');
    } catch (err) {
      showToast(`Failed to preview revision: ${err.message}`, 'error');
    }
  }

  async function restoreRevision(revNum) {
    try {
      const rev = await Api.getRevisionContent(state.currentDocId, revNum);
      const beforeText = docModel.getText();
      const beforeSelections = JSON.parse(JSON.stringify(editorView.selections));

      docModel.setText(rev.content);
      editorView.setSelections([{ anchor: { line: 0, col: 0 }, head: { line: 0, col: 0 } }]);

      // Record restore as an unsaved Undo action
      undoManager.recordAction({
        beforeText,
        afterText: rev.content,
        beforeSelections,
        afterSelections: editorView.selections,
        type: 'restore_revision',
        forceNewGroup: true
      });

      updateDirtyState();
      updateDocumentStats();
      editorView.render();
      editorView.focus();

      if (!el.previewModal.classList.contains('hidden')) {
        el.previewModal.classList.add('hidden');
      }

      showToast(`Revision ${revNum} restored as an unsaved edit. Press Ctrl+Z to undo or Save to commit.`, 'info', 4500);
    } catch (err) {
      showToast(`Failed to restore revision: ${err.message}`, 'error');
    }
  }

  // Find and Replace Controls
  function toggleFindPanel(show) {
    if (show === undefined) {
      show = el.findPanel.classList.contains('hidden');
    }
    if (show) {
      el.findPanel.classList.remove('hidden');
      // If there's selected text in editor, populate find input
      const selected = docModel.getSelectedText(editorView.getPrimarySelection());
      if (selected && !selected.includes('\n')) {
        el.findInput.value = selected;
      }
      el.findInput.focus();
      el.findInput.select();
      updateFindMatches();
    } else {
      el.findPanel.classList.add('hidden');
      findEngine.setQuery('');
      editorView.setSearchHighlights([], -1);
      editorView.focus();
    }
  }

  function updateFindMatches() {
    const query = el.findInput.value;
    const caseSensitive = el.caseSensitiveCheckbox.checked;
    findEngine.setQuery(query, caseSensitive);
    const matches = findEngine.updateMatches(docModel);

    if (!query) {
      el.matchCount.textContent = '';
      editorView.setSearchHighlights([], -1);
      return;
    }

    if (matches.length === 0) {
      el.matchCount.textContent = 'No matches';
      editorView.setSearchHighlights([], -1);
      return;
    }

    // Determine nearest match
    const primary = editorView.getPrimarySelection();
    findEngine.currentIndex = findEngine.findNearestMatchIndex(primary.head, docModel);
    const current = findEngine.getCurrentMatch();

    el.matchCount.textContent = `${findEngine.currentIndex + 1} of ${matches.length}`;
    editorView.setSearchHighlights(matches, findEngine.currentIndex);
  }

  function jumpToCurrentMatch() {
    const match = findEngine.getCurrentMatch();
    if (!match) return;
    el.matchCount.textContent = `${findEngine.currentIndex + 1} of ${findEngine.matches.length}`;
    editorView.setSelections([{ anchor: match.start, head: match.end }]);
    editorView.setSearchHighlights(findEngine.matches, findEngine.currentIndex);
    editorView.scrollToCursor();
  }

  // Find Event Listeners
  el.btnFind.addEventListener('click', () => toggleFindPanel());
  el.btnCloseFind.addEventListener('click', () => toggleFindPanel(false));

  el.findInput.addEventListener('input', () => {
    updateFindMatches();
    if (findEngine.matches.length > 0) {
      jumpToCurrentMatch();
    }
  });

  el.caseSensitiveCheckbox.addEventListener('change', () => {
    updateFindMatches();
    if (findEngine.matches.length > 0) {
      jumpToCurrentMatch();
    }
  });

  el.findInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      if (e.shiftKey) {
        findEngine.prevMatch();
      } else {
        findEngine.nextMatch();
      }
      jumpToCurrentMatch();
    } else if (e.key === 'Escape') {
      e.preventDefault();
      // "When the Find input has focus, Escape should return focus to the editing area without changing the current document selection"
      editorView.focus();
    }
  });

  el.replaceInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      replaceCurrentMatch();
    } else if (e.key === 'Escape') {
      e.preventDefault();
      editorView.focus();
    }
  });

  el.btnFindNext.addEventListener('click', () => {
    findEngine.nextMatch();
    jumpToCurrentMatch();
  });

  el.btnFindPrev.addEventListener('click', () => {
    findEngine.prevMatch();
    jumpToCurrentMatch();
  });

  function replaceCurrentMatch() {
    findEngine.setReplaceText(el.replaceInput.value);
    const res = findEngine.replaceCurrent(docModel);
    if (!res) return;

    undoManager.recordAction({
      beforeText: res.beforeText,
      afterText: res.afterText,
      beforeSelections: [res.selection],
      afterSelections: [res.selection],
      type: 'replace',
      forceNewGroup: true
    });

    updateDirtyState();
    updateDocumentStats();
    jumpToCurrentMatch();
    editorView.render();
  }

  function replaceAllMatches() {
    findEngine.setReplaceText(el.replaceInput.value);
    const res = findEngine.replaceAll(docModel);
    if (res.count === 0) {
      showToast('No matches to replace', 'info');
      return;
    }

    undoManager.recordAction({
      beforeText: res.beforeText,
      afterText: res.afterText,
      beforeSelections: JSON.parse(JSON.stringify(editorView.selections)),
      afterSelections: JSON.parse(JSON.stringify(editorView.selections)),
      type: 'replace_all',
      forceNewGroup: true
    });

    updateDirtyState();
    updateDocumentStats();
    updateFindMatches();
    editorView.render();
    showToast(`Replaced ${res.count} occurrence(s)`, 'success');
  }

  el.btnReplaceCurrent.addEventListener('click', replaceCurrentMatch);
  el.btnReplaceAll.addEventListener('click', replaceAllMatches);

  // Toolbar & General Action Listeners
  el.btnSave.addEventListener('click', () => saveCurrentReport());
  el.btnUndo.addEventListener('click', () => editorView.performUndo());
  el.btnRedo.addEventListener('click', () => editorView.performRedo());

  el.btnHistory.addEventListener('click', () => {
    const isHidden = el.historySidebar.classList.contains('hidden');
    if (isHidden) {
      refreshRevisionsList();
      el.historySidebar.classList.remove('hidden');
    } else {
      el.historySidebar.classList.add('hidden');
    }
  });

  el.btnCloseHistory.addEventListener('click', () => {
    el.historySidebar.classList.add('hidden');
  });

  // Report Switcher
  el.reportSelect.addEventListener('change', (e) => {
    const selectedId = e.target.value;
    if (state.isDirty) {
      if (!confirm('You have unsaved changes in the current report. Switch report anyway and discard unsaved edits?')) {
        e.target.value = state.currentDocId;
        return;
      }
    }
    loadDocument(selectedId);
  });

  // Conflict Modal Actions
  el.btnConflictKeep.addEventListener('click', () => {
    el.conflictModal.classList.add('hidden');
    showToast('Keeping unsaved draft in editor. You may review and save when ready.', 'info', 3500);
    editorView.focus();
  });

  el.btnConflictPreview.addEventListener('click', async () => {
    el.conflictModal.classList.add('hidden');
    try {
      const doc = await Api.getReport(state.currentDocId);
      previewRevision(doc.current_revision);
    } catch (err) {
      showToast('Failed to fetch server revision for preview', 'error');
    }
  });

  el.btnConflictReload.addEventListener('click', () => {
    el.conflictModal.classList.add('hidden');
    loadDocument(state.currentDocId);
  });

  // Preview Modal Actions
  el.btnClosePreview.addEventListener('click', () => {
    el.previewModal.classList.add('hidden');
    editorView.focus();
  });

  el.btnRestorePreview.addEventListener('click', () => {
    if (state.previewRevision) {
      restoreRevision(state.previewRevision.revision_number);
    }
  });

  // Initial Load
  await loadReportsList();
  await loadDocument('incident-alpha');
});

/* PatchPad Stylesheet */

:root {
  --bg-app: #0f172a;
  --bg-header: #1e293b;
  --bg-surface: #1e293b;
  --bg-sidebar: #0f172a;
  --bg-editor: #090d16;
  --bg-gutter: #0f172a;
  --bg-hover: #334155;
  --bg-active: #475569;
  --bg-modal: #1e293b;
  --bg-dialog-overlay: rgba(0, 0, 0, 0.75);

  --border-color: #334155;
  --border-focus: #3b82f6;

  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-muted: #64748b;
  --text-gutter: #475569;
  --text-gutter-active: #93c5fd;

  --accent-primary: #3b82f6;
  --accent-primary-hover: #2563eb;
  --accent-success: #10b981;
  --accent-warning: #f59e0b;
  --accent-danger: #ef4444;
  --accent-danger-hover: #dc2626;

  --selection-bg: rgba(59, 130, 246, 0.35);
  --search-match-bg: rgba(234, 179, 8, 0.4);
  --search-match-active: rgba(249, 115, 22, 0.75);
  --caret-color: #60a5fa;

  --font-ui: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg-app);
  color: var(--text-primary);
  font-family: var(--font-ui);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* App Container Layout */
.app-layout {
  display: flex;
  flex-direction: column;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
}

/* Header */
.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 16px;
  background-color: var(--bg-header);
  border-bottom: 1px solid var(--border-color);
  min-height: 52px;
  flex-shrink: 0;
  z-index: 20;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  flex: 1;
}

.brand {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--accent-primary);
  font-weight: 700;
  font-size: 16px;
  letter-spacing: -0.02em;
  white-space: nowrap;
}

.brand-icon {
  color: var(--accent-primary);
}

.divider-v {
  width: 1px;
  height: 24px;
  background-color: var(--border-color);
  flex-shrink: 0;
}

.divider-v.small {
  height: 14px;
}

.doc-info {
  display: flex;
  flex-direction: column;
  min-width: 0;
  overflow: hidden;
}

.doc-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.doc-author {
  font-size: 11px;
  color: var(--text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.header-center {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.report-switcher {
  display: flex;
  align-items: center;
  gap: 6px;
}

.switcher-label {
  font-size: 12px;
  color: var(--text-secondary);
  font-weight: 500;
}

.report-select {
  background-color: var(--bg-app);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 4px 10px;
  font-size: 12px;
  font-family: inherit;
  outline: none;
  cursor: pointer;
  max-width: 240px;
}

.report-select:focus {
  border-color: var(--border-focus);
}

.header-right.toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

/* Status Badges */
.status-badge {
  font-size: 11px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 12px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.badge-saved {
  background-color: rgba(16, 185, 129, 0.15);
  color: var(--accent-success);
  border: 1px solid rgba(16, 185, 129, 0.3);
}

.badge-unsaved {
  background-color: rgba(245, 158, 11, 0.15);
  color: var(--accent-warning);
  border: 1px solid rgba(245, 158, 11, 0.3);
}

.badge-saving {
  background-color: rgba(59, 130, 246, 0.15);
  color: var(--accent-primary);
  border: 1px solid rgba(59, 130, 246, 0.3);
}

.badge-conflict {
  background-color: rgba(239, 68, 68, 0.2);
  color: var(--accent-danger);
  border: 1px solid rgba(239, 68, 68, 0.4);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 500;
  font-family: inherit;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 0.15s, border-color 0.15s, opacity 0.15s;
  user-select: none;
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.btn-primary {
  background-color: var(--accent-primary);
  color: #ffffff;
}

.btn-primary:hover:not(:disabled) {
  background-color: var(--accent-primary-hover);
}

.btn-secondary {
  background-color: var(--bg-hover);
  color: var(--text-primary);
  border-color: var(--border-color);
}

.btn-secondary:hover:not(:disabled) {
  background-color: var(--bg-active);
  border-color: #64748b;
}

.btn-danger {
  background-color: var(--accent-danger);
  color: #ffffff;
}

.btn-danger:hover:not(:disabled) {
  background-color: var(--accent-danger-hover);
}

.btn-icon {
  background-color: transparent;
  color: var(--text-secondary);
  padding: 6px;
  border-radius: 6px;
}

.btn-icon:hover:not(:disabled) {
  background-color: var(--bg-hover);
  color: var(--text-primary);
}

.btn-sm {
  padding: 4px 8px;
  font-size: 12px;
}

.btn-group {
  display: flex;
  align-items: center;
  gap: 2px;
  background-color: var(--bg-app);
  padding: 2px;
  border-radius: 6px;
  border: 1px solid var(--border-color);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

/* Find & Replace Panel */
.find-panel {
  position: absolute;
  top: 60px;
  right: 20px;
  z-index: 30;
  background-color: var(--bg-header);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 10px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.5);
  min-width: 360px;
}

.find-panel.hidden {
  display: none !important;
}

.find-row, .replace-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.input-with-icon {
  position: relative;
  flex: 1;
  display: flex;
  align-items: center;
}

.input-icon {
  position: absolute;
  left: 8px;
  color: var(--text-muted);
  pointer-events: none;
}

.input-with-icon input {
  width: 100%;
  background-color: var(--bg-app);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 5px 8px 5px 28px;
  font-size: 13px;
  font-family: inherit;
  outline: none;
}

.input-with-icon input:focus {
  border-color: var(--border-focus);
}

.match-count {
  font-size: 12px;
  color: var(--text-secondary);
  min-width: 50px;
  text-align: right;
  white-space: nowrap;
}

.case-sensitive-toggle {
  display: flex;
  align-items: center;
  cursor: pointer;
  font-size: 12px;
  font-weight: 600;
  padding: 3px 6px;
  border-radius: 4px;
  background-color: var(--bg-app);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  user-select: none;
}

.case-sensitive-toggle input {
  display: none;
}

.case-sensitive-toggle:has(input:checked) {
  background-color: var(--accent-primary);
  color: #ffffff;
  border-color: var(--accent-primary);
}

.close-btn {
  font-size: 14px;
  padding: 2px 6px;
}

/* Main Workspace */
.main-workspace {
  display: flex;
  flex: 1;
  min-height: 0;
  overflow: hidden;
  position: relative;
}

/* Editor Viewport & Container */
.editor-viewport {
  flex: 1;
  min-width: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  background-color: var(--bg-editor);
  outline: none;
}

.patchpad-editor-wrapper {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: var(--font-mono);
  font-size: 14px;
  line-height: 24px;
}

.patchpad-input-capture {
  position: absolute;
  top: -9999px;
  left: -9999px;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
  border: none;
  outline: none;
  resize: none;
  z-index: -1;
}

.patchpad-scroll-container {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  overflow-y: scroll;
  overflow-x: auto;
  cursor: text;
}

.patchpad-sizer {
  position: absolute;
  top: 0;
  left: 0;
  pointer-events: none;
}

.patchpad-layers-container {
  position: absolute;
  left: 0;
  right: 0;
  display: flex;
  pointer-events: none;
}

.patchpad-gutter {
  width: 60px;
  flex-shrink: 0;
  background-color: var(--bg-gutter);
  border-right: 1px solid var(--border-color);
  user-select: none;
  text-align: right;
  padding-right: 12px;
  color: var(--text-gutter);
  font-size: 12px;
}

.patchpad-gutter-line {
  line-height: 24px;
}

.patchpad-gutter-line.active {
  color: var(--text-gutter-active);
  font-weight: 600;
}

.patchpad-content {
  position: relative;
  flex: 1;
  min-width: 0;
  padding-left: 12px;
}

.patchpad-text-layer,
.patchpad-selection-layer,
.patchpad-search-highlights-layer,
.patchpad-cursor-layer {
  position: absolute;
  top: 0;
  left: 12px;
  right: 0;
  bottom: 0;
  pointer-events: none;
}

.patchpad-text-layer {
  color: var(--text-primary);
  white-space: pre;
  tab-size: 2;
}

.patchpad-line {
  height: 24px;
  line-height: 24px;
}

.patchpad-measure-span {
  position: absolute;
  visibility: hidden;
  white-space: pre;
  font-family: inherit;
  font-size: inherit;
  line-height: inherit;
}

.patchpad-selection-rect {
  position: absolute;
  background-color: var(--selection-bg);
  border-radius: 2px;
}

.patchpad-search-rect {
  position: absolute;
  background-color: var(--search-match-bg);
  border-radius: 2px;
}

.patchpad-search-rect.active-match {
  background-color: var(--search-match-active);
  box-shadow: 0 0 0 1px #f97316;
}

.patchpad-caret {
  position: absolute;
  width: 2px;
  background-color: var(--caret-color);
  box-shadow: 0 0 4px rgba(96, 165, 250, 0.8);
  pointer-events: none;
  z-index: 10;
}

.patchpad-caret.blinking {
  animation: caret-blink 1.05s step-end infinite;
}

@keyframes caret-blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

/* History Sidebar */
.history-sidebar {
  width: 320px;
  background-color: var(--bg-sidebar);
  border-left: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  z-index: 15;
}

.history-sidebar.hidden {
  display: none !important;
}

.sidebar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-color);
}

.sidebar-header h3 {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
}

.sidebar-description {
  padding: 8px 16px;
  font-size: 11px;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-color);
  background-color: rgba(30, 41, 59, 0.4);
}

.history-list {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.history-item {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  transition: border-color 0.15s;
}

.history-item.current-revision {
  border-color: var(--accent-primary);
  background-color: rgba(59, 130, 246, 0.08);
}

.history-item-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.history-rev-badge {
  font-weight: 700;
  font-size: 12px;
  color: #93c5fd;
}

.history-current-tag {
  font-size: 10px;
  background-color: rgba(59, 130, 246, 0.2);
  color: var(--accent-primary);
  padding: 1px 6px;
  border-radius: 10px;
  font-weight: 600;
}

.history-item-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  color: var(--text-muted);
}

.history-comment {
  font-size: 12px;
  color: var(--text-secondary);
  font-style: italic;
}

.history-item-actions {
  display: flex;
  gap: 8px;
  margin-top: 4px;
}

.history-item-actions .btn {
  flex: 1;
}

/* Status Bar */
.app-statusbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 16px;
  background-color: var(--bg-header);
  border-top: 1px solid var(--border-color);
  font-size: 12px;
  color: var(--text-secondary);
  min-height: 28px;
  flex-shrink: 0;
  z-index: 20;
}

.statusbar-left, .statusbar-right {
  display: flex;
  align-items: center;
  gap: 10px;
}

.statusbar-center {
  display: flex;
  align-items: center;
}

.statusbar-shortcut-hint {
  font-size: 11px;
  color: var(--text-muted);
